// BuildWorkers builds the handle of workers for ref. Generated relation and alias methods call it.
func BuildWorkers(r *keel.Ref) *WorkersTable {
	return &WorkersTable{
		Handle:         keel.Handle[fleet.Worker]{Ref: r},
		ID:             keelkinds.IdsIDCol{StringCol: keel.StringCol{Col: keel.Col{Ref: r, Index: 0}}},
		OrganizationID: keelkinds.IdsIDCol{StringCol: keel.StringCol{Col: keel.Col{Ref: r, Index: 1}}},
		BusinessUnitID: keelkinds.IdsIDCol{StringCol: keel.StringCol{Col: keel.Col{Ref: r, Index: 2}}},
		ManagerID:      keelkinds.IdsIDCol{StringCol: keel.StringCol{Col: keel.Col{Ref: r, Index: 3}}},
		FirstName:      keel.StringCol{Col: keel.Col{Ref: r, Index: 4}},
		LastName:       keel.StringCol{Col: keel.Col{Ref: r, Index: 5}},
		WholeName:      keel.StringCol{Col: keel.Col{Ref: r, Index: 6}},
		HiredAt:        keel.TimeCol{Col: keel.Col{Ref: r, Index: 7}},
	}
}

// WorkersSchema returns the schema of workers.
func WorkersSchema() *schema.Table { return &workersTable }

// As returns a handle that references workers under its own alias.
func (t *WorkersTable) As(alias string) *WorkersTable { return keel.Alias(t.Ref, alias, BuildWorkers) }

// Manager is the belongs relation.
func (t *WorkersTable) Manager() *WorkersTable { return keel.Path(t.Ref, 0, BuildWorkers) }

// Get returns the workers row with the given key, or keel.ErrNotFound.
func (t *WorkersTable) Get(ctx context.Context, db *keel.DB, key ids.ID) (*fleet.Worker, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newWorker() unsafe.Pointer { return unsafe.Pointer(new(fleet.Worker)) }

func newNWorker(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fleet.Worker, n)))
}

func ptrWorker(p unsafe.Pointer, c int32) any {
	r := (*fleet.Worker)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (**string)(unsafe.Pointer(&r.ManagerID))
	case 4:
		return &r.FirstName
	case 5:
		return &r.LastName
	case 6:
		return &r.WholeName
	case 7:
		return &r.HiredAt
	}
	return nil
}

func valueWorker(p unsafe.Pointer, c int32) any {
	r := (*fleet.Worker)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		if r.ManagerID == nil {
			return nil
		}
		return string(*r.ManagerID)
	case 4:
		return r.FirstName
	case 5:
		return r.LastName
	case 6:
		return r.WholeName
	case 7:
		return r.HiredAt
	}
	return nil
}

func attachWorker(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fleet.Worker)(p)
	switch rel {
	case 0:
		r.Manager = (*fleet.Worker)(child)
	}
}

func beforeSaveWorker(ctx context.Context, p unsafe.Pointer) error {
	return (*fleet.Worker)(p).BeforeSave(ctx)
}

func afterLoadWorker(ctx context.Context, p unsafe.Pointer) error {
	return (*fleet.Worker)(p).AfterLoad(ctx)
}

